B.a3s=new A.dz(B.QT,"S\u1eeda nh\xe0, t\xecm th\u1ee3 uy t\xedn g\u1ea7n b\u1ea1n","Th\u1ee3 v\xe0 th\u1ea7u kh\u1eafp An Giang: s\u01a1n, \u0111i\u1ec7n n\u01b0\u1edbc, ch\u1ed1ng th\u1ea5m, x\xe2y s\u1eeda... Xem h\u1ed3 s\u01a1, c\xf4ng tr\xecnh th\u1eadt v\xe0 \u0111\xe1nh gi\xe1 tr\u01b0\u1edbc khi thu\xea.")
B.ux=new A.ak(58671,"MaterialIcons",!1)
B.a3v=new A.dz(B.ux,"\u0110\u0103ng vi\u1ec7c mi\u1ec5n ph\xed, nh\u1eadn b\xe1o gi\xe1","Ch\u1ee7 nh\xe0 m\xf4 t\u1ea3 vi\u1ec7c c\u1ea7n l\xe0m, th\u1ee3 g\u1ea7n b\u1ea1n g\u1eedi b\xe1o gi\xe1. So s\xe1nh r\u1ed3i chat tr\u1ef1c ti\u1ebfp, kh\xf4ng l\u1ed9 s\u1ed1 \u0111i\u1ec7n tho\u1ea1i.")
