B.vN=s(["X\xe2y nh\xe0 nguy\xean c\u0103n","Nh\xe0 c\u1ea5p 4","Bi\u1ec7t th\u1ef1","S\u1eeda ch\u1eefa c\u1ea3i t\u1ea1o","Nh\xe0 x\u01b0\u1edfng","N\u1ed9i th\u1ea5t tr\u1ecdn g\xf3i","Nh\xe0 ph\u1ed1, nh\xe0 l\u1ea7u","Thi\u1ebft k\u1ebf ki\u1ebfn tr\xfac","Thi c\xf4ng ph\u1ea7n th\xf4","Ho\xe0n thi\u1ec7n nh\xe0","Nh\xe0 ti\u1ec1n ch\u1ebf, khung th\xe9p","Nh\xe0 tr\u1ecd, ph\xf2ng tr\u1ecd","Qu\xe1n c\xe0 ph\xea, nh\xe0 h\xe0ng, c\u1eeda h\xe0ng","S\xe2n v\u01b0\u1eddn, ti\u1ec3u c\u1ea3nh","San l\u1ea5p, k\xe8, l\xe0m m\xf3ng","Ch\u1ed1ng th\u1ea5m tr\u1ecdn g\xf3i","\u0110i\u1ec7n n\u01b0\u1edbc c\xf4ng tr\xecnh","H\u1ed3 b\u01a1i, h\u1ed3 c\xe1 Koi"],t.s)
B.WC=s(["T\xecm Th\u1ee3 An Giang l\xe0 n\u01a1i k\u1ebft n\u1ed1i ch\u1ee7 nh\xe0 v\u1edbi th\u1ee3 v\xe0 nh\xe0 th\u1ea7u. \u1ee8ng d\u1ee5ng kh\xf4ng ph\u1ea3i b\xean thu\xea hay b\xean thi c\xf4ng.","Gi\xe1 c\u1ea3, ch\u1ea5t l\u01b0\u1ee3ng, ti\u1ebfn \u0111\u1ed9, b\u1ea3o h\xe0nh v\xe0 thanh to\xe1n do hai b\xean t\u1ef1 th\u1ecfa thu\u1eadn v\xe0 ch\u1ecbu tr\xe1ch nhi\u1ec7m."],t.s)
B.a2N=new A.ai("1. \u1ee8ng d\u1ee5ng l\xe0m g\xec",B.WC)
B.W6=s(["B\u1ea1n ph\u1ea3i t\u1eeb 18 tu\u1ed5i, d\xf9ng t\xean v\xe0 th\xf4ng tin th\u1eadt.","M\u1ed7i ng\u01b0\u1eddi ch\u1ec9 d\xf9ng m\u1ed9t t\xe0i kho\u1ea3n. B\u1ea1n ch\u1ecbu tr\xe1ch nhi\u1ec7m m\u1ecdi ho\u1ea1t \u0111\u1ed9ng tr\xean t\xe0i kho\u1ea3n c\u1ee7a m\xecnh."],t.s)
B.a3e=new A.ai("2. T\xe0i kho\u1ea3n",B.W6)
B.Vv=s(["B\u1ea1n ch\u1ecbu tr\xe1ch nhi\u1ec7m v\u1ec1 tin \u0111\u0103ng, b\xe1o gi\xe1, tin nh\u1eafn, b\xe0i vi\u1ebft v\xe0 \u0111\xe1nh gi\xe1 c\u1ee7a m\xecnh.","Qu\u1ea3n tr\u1ecb vi\xean c\xf3 quy\u1ec1n \u1ea9n ho\u1eb7c x\xf3a n\u1ed9i dung vi ph\u1ea1m m\xe0 kh\xf4ng c\u1ea7n b\xe1o tr\u01b0\u1edbc."],t.s)
B.a34=new A.ai("3. N\u1ed9i dung b\u1ea1n \u0111\u0103ng",B.Vv)
B.Wa=s(["M\u1ee9c ph\xed v\xe0 th\u1eddi h\u1ea1n \u0111\u01b0\u1ee3c ghi r\xf5 trong \u1ee9ng d\u1ee5ng tr\u01b0\u1edbc khi b\u1ea1n \u0111\u0103ng k\xfd.","T\xe0i kho\u1ea3n b\u1ecb kh\xf3a v\xec vi ph\u1ea1m s\u1ebd kh\xf4ng \u0111\u01b0\u1ee3c ho\xe0n ph\xed ph\u1ea7n c\xf2n l\u1ea1i."],t.s)
B.a2X=new A.ai("4. G\xf3i Pro v\xe0 Ghim",B.Wa)
B.X4=s(["\u1ee8ng d\u1ee5ng kh\xf4ng ch\u1ecbu tr\xe1ch nhi\u1ec7m v\u1ec1 tranh ch\u1ea5p gi\u1eefa ng\u01b0\u1eddi d\xf9ng, nh\u01b0ng s\u1ebd h\u1ed7 tr\u1ee3 xem x\xe9t khi c\xf3 b\xe1o c\xe1o.","Khi c\xf3 y\xeau c\u1ea7u b\u1eb1ng v\u0103n b\u1ea3n c\u1ee7a c\u01a1 quan nh\xe0 n\u01b0\u1edbc c\xf3 th\u1ea9m quy\u1ec1n, ch\xfang t\xf4i s\u1ebd cung c\u1ea5p th\xf4ng tin theo quy \u0111\u1ecbnh ph\xe1p lu\u1eadt."],t.s)
